// 1. The classic 'var' loop problem (shared function-scoped variable)
for (var i = 0; i < 3; i++) {
  setTimeout(() => console.log("var i:", i), 10); // Prints: 3, 3, 3 !
}

// 2. The ES6 'let' solution (fresh lexical block-scoped binding per iteration)
for (let j = 0; j < 3; j++) {
  setTimeout(() => console.log("let j:", j), 10); // Prints: 0, 1, 2 !
}

// 3. Temporal Dead Zone (TDZ):
// Accessing a 'let' or 'const' variable before its declaration line throws ReferenceError
// console.log(tdzVar); // ReferenceError: Cannot access 'tdzVar' before initialization
let tdzVar = "active";

const username = "Alice";
const cartTotal = 89.95;

// Standard template literal with interpolation and multi-line formatting
const receipt = `
  Receipt For: ${username.toUpperCase()}
  Items Total: $${cartTotal.toFixed(2)}
  Status: ${cartTotal > 50 ? "Free Shipping Qualified" : "Standard Shipping"}
`;
console.log(receipt);

// Tagged template function (useful for custom formatting or SQL/HTML escaping)
function highlight(strings, ...values) {
  return strings.reduce((acc, str, i) => {
    const val = values[i] !== undefined ? `<mark>${values[i]}</mark>` : "";
    return `${acc}${str}${val}`;
  }, "");
}

const formatted = highlight`Hello ${username}, you have ${3} new messages.`;
console.log(formatted); // Hello <mark>Alice</mark>, you have <mark>3</mark> new messages.

// 1. Rest Parameter: Gathers remaining elements into an array
function calculateAverage(category, ...scores) {
  const total = scores.reduce((sum, s) => sum + s, 0);
  return `${category} Average: ${(total / scores.length).toFixed(1)}`;
}
console.log(calculateAverage("Math Exams", 88, 92, 79, 95));

// 2. Spread Operator on Arrays (non-mutating clone and merge)
const fruits = ["apple", "banana"];
const veggies = ["carrot", "broccoli"];
const foodBasket = [...fruits, "orange", ...veggies];

// 3. Spread Operator on Objects (shallow clone with overrides)
const baseSettings = { theme: "light", notifications: true, volume: 50 };
const userCustomized = { ...baseSettings, theme: "dark", volume: 75 };

console.log(userCustomized); // { theme: 'dark', notifications: true, volume: 75 }

